      this.focusBeforeExpand = null; this.printOpen = new Map();
      const ide = document.createElement('section'); this.ide = ide;
      ide.className = 'source-ide'; ide.dataset.projectId = project.id;
      ide.setAttribute('aria-label', project.rootLabel + ' 源码阅读器');
