        '<div class="ide-file-tree" aria-label="文件与文件夹"></div><p class="ide-empty" role="status" hidden>没有匹配的文件</p></aside></div>';
      this.tabs = ide.querySelector('.ide-tabs'); this.tree = ide.querySelector('.ide-file-tree');
