      const scope = excerpt?'源码节选':(/中文注释/.test(file.contentScope||'')?'完整文件 · 中文注释':'完整文件');
      this.ide.querySelector('.ide-status-count').textContent = lines + ' 行 · ' + (excerpt?'节选内行号':(file.lineNumberMeaning||'文件内行号'));
      this.ide.querySelector('.ide-status-file').textContent = '只读 · ' + scope;
